const retireInterruptedIndexerQueries = `-- name: RetireInterruptedIndexerQueries :exec
UPDATE indexer_query SET state='failed',error='execution interrupted',finished_at=clock_timestamp() WHERE indexer_id=$1 AND state='running'
`

func (q *Queries) RetireInterruptedIndexerQueries(ctx context.Context, indexerID uuid.UUID) error {
	_, err := q.db.Exec(ctx, retireInterruptedIndexerQueries, indexerID)
	return err
}

const returnRoundEndpoint = `-- name: ReturnRoundEndpoint :execrows
UPDATE search_round_endpoint SET query_id=$3,state=$4 WHERE round_id=$1 AND indexer_id=$2 AND state='pending'
`

type ReturnRoundEndpointParams struct {
	RoundID   uuid.UUID
	IndexerID uuid.UUID
	QueryID   pgtype.UUID
	State     string
}

func (q *Queries) ReturnRoundEndpoint(ctx context.Context, arg ReturnRoundEndpointParams) (int64, error) {
	result, err := q.db.Exec(ctx, returnRoundEndpoint,
		arg.RoundID,
		arg.IndexerID,
		arg.QueryID,
		arg.State,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

